#!/usr/bin/env python3
"""Compile the built-in contracts and emit bytecode + fixtures.

Same pattern as gen_selectors.py: build-time generator, fail closed.
Reads contracts/*.sol + solc-version.txt; writes to OUTDIR:
  builtins.gen.h    C arrays (runtime bytecode, fixtures) for the firmware
  builtins.gen.json same content as hex, for the py-evm oracle

The fixture is the v1 initial state (a state file in Phase 2):
  erc20: totalSupply = 1000 (slot 2), balances[alice] = 1000 at
         keccak(abi.encode(alice, 0)); balances[bob] = 0 (default).
  amm:   empty (pure function).
The firmware and the oracle read the same slots from this output.

Usage: gen_builtins.py <contracts-dir> <outdir>
"""

import json
import sys
from pathlib import Path

ALICE = "1111111111111111111111111111111111111111"
BOB = "2222222222222222222222222222222222222222"
SPENDER = "3333333333333333333333333333333333333333"


def c_bytes(name, data: bytes) -> str:
    body = ",".join(f"0x{b:02x}" for b in data)
    # Non-static: builtins.gen.h is included once (builtins.c); eth.c uses extern.
    return f"const uint8_t {name}[] = {{{body}}};\nconst size_t {name}_len = sizeof({name});\n"


def main() -> int:
    cdir, outdir = Path(sys.argv[1]), Path(sys.argv[2])
    want_solc = (cdir / "solc-version.txt").read_text().strip()
    try:
        import solcx
    except ImportError:
        print("FATAL: py-solc-x required (pip install py-solc-x)", file=sys.stderr)
        return 1
    if want_solc not in [str(v) for v in solcx.get_installed_solc_versions()]:
        print(f"installing solc {want_solc}...", file=sys.stderr)
        solcx.install_solc(want_solc)
    solcx.set_solc_version(want_solc)

    files = [str(cdir / "MiniERC20.sol"), str(cdir / "Amm.sol")]
    out = solcx.compile_files(
        files, output_values=["bin-runtime", "storage-layout"],
        optimize=True, metadata_hash="none",
    )
    by_name = {k.split(":")[-1]: v for k, v in out.items()}
    erc = by_name["MiniERC20"]
    amm = by_name["Amm"]
    erc_rt = bytes.fromhex(erc["bin-runtime"])
    amm_rt = bytes.fromhex(amm["bin-runtime"])
    # Layout assertion: the fixture math below depends on these slots.
    slots = {e["label"]: int(e["slot"]) for e in erc["storage-layout"]["storage"]}
    assert slots.get("balanceOf") == 0, slots
    assert slots.get("allowance") == 1, slots
    assert slots.get("totalSupply") == 2, slots
    # No metadata trailer (--metadata-hash none must leave no CBOR).
    for tag, rt in (("erc20", erc_rt), ("amm", amm_rt)):
        assert b"\xa2\x64ipfs" not in rt and b"\xa2\x64bzzr" not in rt, tag
        assert len(rt) < 24576, (tag, len(rt))

    from eth_hash.auto import keccak

    def mapslot(addr_hex: str, slot: int) -> bytes:
        return keccak(bytes.fromhex(addr_hex.rjust(64, "0")) + slot.to_bytes(32, "big"))

    fixture = [
        ((2).to_bytes(32, "big"), (1000).to_bytes(32, "big")),  # totalSupply
        (mapslot(ALICE, 0), (1000).to_bytes(32, "big")),         # balances[alice]
    ]

    h = ["#pragma once",
         "// Generated by gen_builtins.py — do not edit.",
         f"// solc {want_solc}, optimize, metadata-hash none.",
         "#include <stdint.h>", "#include <stddef.h>", "",
         c_bytes("builtin_erc20_code", erc_rt),
         c_bytes("builtin_amm_code", amm_rt),
         "typedef struct { uint8_t key[32]; uint8_t val[32]; } builtin_slot_t;",
         "const builtin_slot_t builtin_erc20_fixture[] = {"]
    for k, v in fixture:
        h.append("    { {" + ",".join(f"0x{b:02x}" for b in k) + "}, {" +
                 ",".join(f"0x{b:02x}" for b in v) + "} },")
    h.append("};")
    h.append("const size_t builtin_erc20_fixture_len = sizeof(builtin_erc20_fixture)/sizeof(builtin_slot_t);")
    for tag, addr in (("alice", ALICE), ("bob", BOB), ("spender", SPENDER)):
        h.append("const uint8_t builtin_%s[20] = {%s};" % (
            tag, ",".join(f"0x{addr[i:i+2]}" for i in range(0, 40, 2))))
    (outdir / "builtins.gen.h").write_text("\n".join(h) + "\n")

    js = {
        "solc": want_solc,
        "alice": "0x" + ALICE, "bob": "0x" + BOB, "spender": "0x" + SPENDER,
        "slots": slots,
        "erc20": {"runtime": erc_rt.hex(),
                  "fixture": [[k.hex(), v.hex()] for k, v in fixture]},
        "amm": {"runtime": amm_rt.hex(), "fixture": []},
    }
    (outdir / "builtins.gen.json").write_text(json.dumps(js, indent=1) + "\n")
    print(f"gen_builtins: solc {want_solc} erc20={len(erc_rt)}B amm={len(amm_rt)}B "
          f"fixture={len(fixture)} slots", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
